/**
 * TraceNode
 *
 * Recursive node structure for rendering trace hierarchy in the frontend
 */
export type TraceNode = {
    /**
     * Duration
     *
     * Human-readable duration (e.g., '123ms', '1.5s')
     */
    duration: string;
    /**
     * End Time
     *
     * End time (Pydantic auto-serializes to ISO 8601)
     */
    end_time: string;
    /**
     * Error
     *
     * Error message if status is ERROR
     */
    error?: string | null;
    /**
     * Extra Data
     *
     * Flexible field for custom attributes and additional data
     */
    extra_data?: {
        [key: string]: unknown;
    } | null;
    /**
     * Id
     *
     * Span ID
     */
    id: string;
    /**
     * Input
     *
     * Input to the span
     */
    input?: string | null;
    /**
     * Metadata
     *
     * Additional span attributes and data
     */
    metadata?: {
        [key: string]: unknown;
    } | null;
    /**
     * Name
     *
     * Span name (e.g., 'agent.run', 'llm.invoke')
     */
    name: string;
    /**
     * Output
     *
     * Output from the span
     */
    output?: string | null;
    /**
     * Spans
     *
     * Child spans in the trace hierarchy
     */
    spans?: Array<TraceNode> | null;
    /**
     * Start Time
     *
     * Start time (Pydantic auto-serializes to ISO 8601)
     */
    start_time: string;
    /**
     * Status
     *
     * Status code (OK, ERROR)
     */
    status: string;
    /**
     * Step Type
     *
     * Workflow step type (Step, Condition, function, Agent, Team)
     */
    step_type?: string | null;
    /**
     * Type
     *
     * Span kind (AGENT, TEAM, WORKFLOW, LLM, TOOL)
     */
    type: string;
};

/**
 * TraceSearchGroupBy
 *
 * Grouping options for trace search results.
 */
export type TraceSearchGroupBy = 'run' | 'session';

/**
 * TraceSearchRequest
 *
 * Request body for POST /traces/search with advanced filtering.
 *
 * The filter field accepts a FilterExpr DSL dict supporting composable queries
 * with AND/OR/NOT logic and operators like EQ, NEQ, GT, GTE, LT, LTE, IN, CONTAINS, STARTSWITH.
 *
 * Example for run grouping (default):
 * {
 * "filter": {
 * "op": "AND",
 * "conditions": [
 * {"op": "EQ", "key": "status", "value": "OK"},
 * {"op": "CONTAINS", "key": "user_id", "value": "admin"}
 * ]
 * },
 * "group_by": "run",
 * "page": 1,
 * "limit": 20
 * }
 *
 * Example for session grouping:
 * {
 * "filter": {"op": "EQ", "key": "agent_id", "value": "my-agent"},
 * "group_by": "session",
 * "page": 1,
 * "limit": 20
 * }
 */
export type TraceSearchRequest = {
    /**
     * Filter
     *
     * FilterExpr DSL as JSON dict. Supports operators: EQ, NEQ, GT, GTE, LT, LTE, IN, CONTAINS, STARTSWITH, AND, OR, NOT.
     */
    filter?: {
        [key: string]: unknown;
    } | null;
    /**
     * Grouping mode: 'run' returns individual TraceDetail, 'session' returns aggregated TraceSessionStats.
     */
    group_by?: TraceSearchGroupBy;
    /**
     * Limit
     *
     * Number of traces per page (max 100)
     */
    limit?: number;
    /**
     * Page
     *
     * Page number (1-indexed)
     */
    page?: number;
};

